	if err != nil {
		fmt.Fprintln(os.Stderr, "lcprac: sync skipped:", err)
		return
	}
	if delta.NewWritten, delta.UpdatedWritten, err = syncOwnDrills(client, true); err != nil {
		// The history half already worked, so this is a warning rather than a
